"""The HTTP run host: health, schema, start a run (generated by adk_v2/6.0.0)."""

import httpx

from retail_kyc_onboarding._engine.server import create_app


async def test_host_serves_health_schema_and_a_run(offline_engine):
    """The host serves health, the OpenAPI schema, docs and export info, and accepts a run."""
    app = create_app(engine=offline_engine)
    async with app.router.lifespan_context(app):
        transport = httpx.ASGITransport(app=app)
        async with httpx.AsyncClient(transport=transport, base_url="http://test") as client:
            health = await client.get("/healthz")
            assert health.status_code == 200 and health.json()["status"] in {"ok", "degraded"}
            schema = await client.get("/openapi.json")
            assert schema.status_code == 200 and "/v1/runs" in schema.json()["paths"]
            assert (await client.get("/docs")).status_code == 200
            info = await client.get("/v1/export")
            assert info.status_code == 200 and info.json()["export"]["id"] == "plan-retail_kyc_onboarding"
            run = await client.post("/v1/runs", json={"message": "hello"})
            assert run.status_code == 200, run.text
            assert "session_id" in run.json() or "status" in run.json()


async def test_the_documented_a2a_request_returns_a_task(offline_engine):
    """The `message/send` request of docs/INTEGRATION.md starts a run and answers with an A2A task."""
    import json
    import re
    from pathlib import Path

    doc = (Path(__file__).resolve().parents[2] / "docs" / "INTEGRATION.md").read_text(encoding="utf-8")
    request = json.loads(re.search(r"^```json\n(.*?)^```", doc, re.MULTILINE | re.DOTALL).group(1))
    app = create_app(engine=offline_engine)
    transport = httpx.ASGITransport(app=app)
    async with app.router.lifespan_context(app), httpx.AsyncClient(transport=transport, base_url="http://test") as client:
        answer = (await client.post("/a2a", json=request)).json()
    assert "error" not in answer, answer
    assert answer["result"]["kind"] == "task"
    assert answer["result"]["status"]["state"] in {"input-required", "completed"}
